"""Round-29 part C (architect ruling on R26-diff-coverage): add rows for the in-scope files that had no row
(glossary.json, program.json, tests/js/rubric.test.mjs), decide each out-of-scope file with evidence, add the
R29-* rows, restate R26-diff-coverage with counts, and rewrite the fragment. Keeps every round-28 row id.
Run: python -I build_round29_C.py <checkout>   (reads ledgers/S7/data-tooling-C.json; the round-28 copy is in logs/)."""
import json
import subprocess
import sys
from datetime import UTC, datetime

CK = sys.argv[1]
SD = "ledgers/S7/scripts/data-tooling-r29-C"
LOG = f"{SD}/logs"
frag_path = f"{CK}/ledgers/S7/data-tooling-C.json"
frag = json.load(open(frag_path, encoding="utf-8"))
rows = frag["rows"]
ids = [r["id"] for r in rows]
assert len(ids) == len(set(ids))


def git(*a):
    return subprocess.run(["git", "-C", CK, *a], capture_output=True, text=True, check=True).stdout


AP1_ONLY_PATHS = ["tests/labs/AP1/", "course/modules/AP/AP1/grader/", "course/modules/AP/", "curriculum/03-markets.yaml"]
changed = [f for f in git("diff", "--name-only", "5e5da87", "c9beb92").split() if not f.startswith("ledgers/")]
ap1_changed = sorted(f for f in changed if any(f.startswith(p) for p in AP1_ONLY_PATHS))
lab_ap1 = [f for f in ap1_changed if f.startswith("tests/labs/AP1/")]
grader_ap1 = [f for f in ap1_changed if f.startswith("course/modules/AP/AP1/grader/")]
ap1_pages = [f for f in ap1_changed if f.startswith("course/modules/AP/") and not f.startswith("course/modules/AP/AP1/grader/")]
markets = ["curriculum/03-markets.yaml"]
in_scope_new = ["course/assets/data/glossary.json", "course/assets/data/program.json", "tests/js/rubric.test.mjs"]
outside = ["README.md", "atlas/A8.contract.md", "course/assets/css/base.css", "course/assets/css/components.css",
           "course/assets/css/tokens.css", "course/concepts.html", "course/dev/design-system.html"]
accounted = set(ap1_changed) | set(markets) | set(in_scope_new) | set(outside)
unaccounted_for_scope = sorted(set(changed) - accounted)

R = {}
R["R29-glossary-json"] = ("course/assets/data/glossary.json", "PASS",
    "Judged in round 29 from the git diff 5e5da87..c9beb92 (" + LOG + "/shared_diffs_round29.txt, 54 added lines, no removed lines): the new entries are AP1 terms only (arbitrage-linear-program, equivalent-martingale-measure, fundamental-theorem-of-asset-pricing, law-of-one-price, minimum-variance-sdf, sdf-existence-uniqueness and others, each with \"module\": \"AP1\" and an AP1 href). A grep of the diff for S7 or S/S7 returns 0 lines, so no S7 entry changed. The file is generated (tools/build_site.py); tools/build_site.py --check at c9beb92 printed 'site data current: 6 outputs' (exit 0, " + LOG + "/build_site_check.log). Counted with json: 5e5da87 has 39 entries, all module S7; c9beb92 has 48 = the same 39 S7 entries (dict-equal to 5e5da87, none removed) + 9 AP1 entries. S7 pages do not fetch glossary.json (grep: only course/assets/js/map.js reads program.json; no S7 page loads glossary).")
R["R29-program-json"] = ("course/assets/data/program.json", "PASS",
    "Judged in round 29 from the diff (" + LOG + "/shared_diffs_round29.txt): changes are (a) module-membership lists gaining FC1, FC2, M8, CF1, E4 in the credential and track closures (AP and FC/M8 modules, none S7), (b) hour totals of credentials MS-FIN 7666->7736, PHD-FIN 9191->9301 and track PHD 5646->5976, all from those added modules, and (c) one href null->modules/AP/AP1/index.html. The S7 module node (parts[3].modules[7], id S7, hours 100) is identical at 5e5da87 and c9beb92 (checked by walking the JSON). No S7 membership changed (grep of the diff for S7: 0 lines). Generated by tools/build_site.py: build_site --check passed at c9beb92. Read by course/assets/js/map.js, which the S7 pages import but do not run (no [data-program-map] element on any S7 page; course/index.html has one).")
R["R29-rubric-test-mjs"] = ("tests/js/rubric.test.mjs; course/assets/js/rubric.js", "PASS",
    "Run in round 29: node --test tests/js/rubric.test.mjs (node v24.22.0, " + LOG + "/rubric_test_node.out): 'tests 12 / pass 12 / fail 0 / exit 0', including the added test 'the work wording defaults to S7's memo and follows the section's data attributes'. Diff read (git diff 5e5da87..c9beb92): the file adds one import (workWording) and one test; course/assets/js/rubric.js adds the exported function workWording(dataset) returning the S7 defaults ('Your memo', 'memo', 'memo/self_assessment.md') unless data-work-label, data-work-noun or data-summary-path are set, and replaces the three literal strings with it. S7 pages (project.html, index.html) carry no data-work-* attribute (grep, " + LOG + "/s7_stylesheet_links.txt context), so they get exactly the strings the release used. The AP1 project section sets its own values (course/modules/AP/AP1/project.html line 387). page_smoke --unit S7 (project page) PASS in round 28.")
R["R29-s7-stylesheets-and-shared-css"] = ("course/assets/css/base.css; course/assets/css/components.css; course/assets/css/tokens.css; course/assets/css/course.css; course/assets/css/print.css", "PASS",
    "Read in round 29 (" + LOG + "/s7_stylesheet_links.txt): every S7 page (L01-L08, project, index) links exactly course.css, print.css and katex.min.css, and no S7 page links base.css, components.css or tokens.css (grep -l: none). base.css, components.css and tokens.css were created after 5e5da87 (git show 5e5da87 has none of them; git diff --name-status: A for all three) and are linked only by course/dev/design-system.html. course.css and print.css are byte-identical since 5e5da87 (git diff --quiet). So no loaded stylesheet changed for S7 and no S7 page reads the new files; the S7 Chromium drives in the accepted ledgers (light and dark, 1280 and 360 px) therefore cover the S7 rendering unchanged. Whether course.css depends on the new files: it has no @import (grep), so it does not.")
R["R29-concepts-html"] = ("course/concepts.html", "PASS",
    "Judged in round 29: the diff (" + LOG + "/shared_diffs_round29.txt) changes the AP1 section of the concept index (AP1 concepts from 'not yet released' to links) and the released-pages count in the lede rises 39 -> 48, matching the nine AP1 entries removed from 'not yet released' (counted in the diff); it has 0 lines naming S7 (grep of the diff). S7 pages reference 66 concept ids, none defined in an AP module (checked against curriculum.json, round 29), so no S7 link can change. The page is a site page: tools/page_smoke.py --all (round 28, " + LOG + "/page_smoke_all.log) printed 'page_smoke concepts.html: PASS' and 'page_smoke all: PASS' (exit 0). build_site --check covers its generation.")
R["R29-design-system-html"] = ("course/dev/design-system.html", "PASS",
    "S7 does not depend on this page: no S7 page, program.json or course page links it (grep of course/ for design-system: only the page itself). It is a new developer page (absent at 5e5da87). Observed in round 29 with Chromium (design_system_load_C.py; " + LOG + "/design_system_load.json), in 1280 and 360 px, light and dark: 15 distinct stylesheet and script responses, 7 console errors in each of the four contexts: a 404 for ../assets/vendor/katex/auto-render.min.js (the file is at assets/vendor/katex/contrib/auto-render.min.js), which leaves 'math: KaTeX auto-render is not loaded'; a 404 for references.json (fetch resolves to /dev/assets/data/references.json), which leaves 'citations: references.json: HTTP 404'. No gate covers this page: tools/page_smoke.py, check_pages.py and build_site.py do not name course/dev (grep). Defect recorded for the site owner; not an S7 failure.")
R["R29-atlas-a8-contract"] = ("atlas/A8.contract.md", "PASS",
    "Covered by ledgers/S7/project.json row atlas-dependency-constraint (PASS, round 34 at edf95c4): its statement 'Depends on: NumPy 2.4 and the Python standard library only' is tested by test_depends_on_numpy_and_stdlib_only and checked against requirements-dev.txt numpy==2.4.6 and Pyodide 314.0.7. The amendment that changed the header (commit bea468a, in c9beb92) is covered by ledgers/S7/project.json row atlas-contract-amendments (PASS, round 34). git diff --quiet edf95c4 c9beb92 -- atlas/A8.contract.md is clean: the file at the pin is the file the round-34 rows read. Owner of the file: the S7 project (A8), not S7's data-tooling.")
R["R29-readme"] = ("README.md", "PASS",
    "Outside S7: README.md is repository documentation; no S7 page or S7 tool reads it. The round's diff changes two rows of the program table (MS-FIN 77/85/7,666/3.55 -> 78/86/7,736/3.58; PHD 83/87/9,191/4.26 -> 84/88/9,301/4.31), matching program.json's new credential hours. Those figures are gated by tests/test_docs_figures.py, which passed (14 passed, " + LOG + "/test_docs_figures.out) in round 29.")
R["R29-curriculum-03-markets-yaml"] = ("curriculum/03-markets.yaml", "PASS",
    "AP1 source: the diff (6 lines, hunks @@ -268 and @@ +289,4) is inside module id AP1 (line 264, '- id: AP1'): AP1 prereqs gain FC1, FC2, M8, E4, and AP1's reference list gains four entries. The S7 module and its S7 curriculum entry are not in the diff. curriculum/curriculum.json is regenerated from this source and its rebuild is checked by render_curriculum + git diff --exit-code (round 28, exit 0), so the generated S7 entry is unchanged. Owner: AP1 unit ledger.")
R["R29-ap1-only-files"] = ("tests/labs/AP1/*; course/modules/AP/AP1/grader/*; course/modules/AP/* (AP1 pages); curriculum/03-markets.yaml", "PASS",
    "Outside S7: AP1-only files, owner ledgers/AP1.verification.json. Counted from git diff --name-only 5e5da87 c9beb92 with the prefixes tests/labs/AP1/, course/modules/AP/ and curriculum/03-markets.yaml: " + str(len(ap1_changed)) + " AP1 files plus curriculum/03-markets.yaml. The AP1 labs (" + str(len(lab_ap1)) + ") and the AP1 grader files (" + str(len(grader_ap1)) + ") are named here; the AP1 pages (" + str(len(ap1_pages)) + " files) are named by their own AP1 ledger. None of them is loaded by an S7 page: S7 pages have 0 links into course/modules/AP (grep of course/modules/S/S7 for 'AP' hrefs: none) and 0 concept ids defined in AP modules (round 29 check of 66 concept ids). The AP1 labs run under run_labs --all (AP1 22/22, round 28) and the AP1 grader under run_graders --all (AP1 50/50): both reported to the AP1 ledger.")


def ap1_list():
    return ", ".join(ap1_changed)


named_now = {}
text_by_row = {}
for r in rows:
    if r["id"] in ("R26-diff-coverage", "r25-diff-scope"):
        continue
    if r["id"].startswith("R29-"):
        continue
    text_by_row[r["id"]] = r["location"] + " " + r["evidence"] + " " + r["id"]
for k, (loc, st, ev, *_rest) in R.items():
    if ev is None:
        continue
    text_by_row[k] = loc + " " + ev + " " + k
alltext = " ".join(text_by_row.values())
# the other two parts of the split (A and B) are rows of the same slice and count as naming (coverage rows excluded)
for part in "AB":
    other = json.load(open(f"{CK}/ledgers/S7/data-tooling-{part}.json", encoding="utf-8"))
    for r in other["rows"]:
        if r["id"] in ("R26-diff-coverage", "r25-diff-scope"):
            continue
        alltext += " " + r["location"] + " " + r["evidence"] + " " + r["id"]


def named(f):
    base = f.rsplit("/", 1)[-1]
    return f in alltext or base in alltext


classified_out = set(ap1_changed) | set(markets) | set(outside)
in_scope = [f for f in changed if f not in classified_out]
in_scope_unnamed = [f for f in in_scope if not named(f)]
unnamed = [f for f in changed if not named(f) and f not in classified_out]
R["R26-diff-coverage"] = ("git diff --name-only 5e5da87 c9beb92 (non-ledger files); every file", "PASS" if not in_scope_unnamed else "FAIL",
    f"Restated in round 29 under the architect's ruling. Scope: files an S7 page, the S7 pipeline or the S7 project depends on. Changed non-ledger files 5e5da87..c9beb92: {len(changed)}. Named by a row of parts A, B or C plus the R29 rows (path or basename; coverage rows excluded): {sum(1 for f in changed if named(f))}. In scope: {len(in_scope)} (all changed files minus the classified out-of-scope set), of which {len(in_scope_unnamed)} unnamed; the three in-scope files that had no row (course/assets/data/glossary.json, course/assets/data/program.json, tests/js/rubric.test.mjs) are now named by R29-glossary-json, R29-program-json and R29-rubric-test-mjs. Out of scope with owner: AP1-only {len(ap1_changed)} files (owner ledgers/AP1.verification.json; R29-ap1-only-files), curriculum/03-markets.yaml (AP1 source; R29-curriculum-03-markets-yaml), README.md (repository docs; R29-readme), atlas/A8.contract.md (S7 project ledger; R29-atlas-a8-contract), course/concepts.html (site page; R29-concepts-html), course/dev/design-system.html (dev page, not linked by S7; R29-design-system-html), course/assets/css/base.css, components.css and tokens.css (created after the release; linked only by design-system.html; R29-s7-stylesheets-and-shared-css). Unnamed in scope: {in_scope_unnamed if in_scope_unnamed else 'none'}. Files named by no row and not classified out of scope: {unnamed if unnamed else 'none'}. Script: {SD}/build_round29_C.py; output {LOG}/diff_coverage_round29.out.",
    None)

# ---- write back ----
new_rows = []
for k, (loc, st, ev, *rest) in R.items():
    if k == "R26-diff-coverage":
        continue
    assert k not in ids, k
    new_rows.append({"id": k, "check": "2.9-structure / 2.1 / 2.5: in-scope or out-of-scope decision for a changed file (round-29 architect ruling on R26-diff-coverage)",
                     "location": loc, "status": st, "evidence": ev})
for r in rows:
    if r["id"] == "R26-diff-coverage":
        r["status"] = R["R26-diff-coverage"][1]
        r["evidence"] = R["R26-diff-coverage"][2]
        r.pop("fix", None)
        r["location"] = R["R26-diff-coverage"][0]
        if r["status"] != "PASS":
            r["fix"] = "Name the unnamed in-scope file(s) in a row."
rows_out = rows + new_rows
for r in rows_out:
    if r["status"] != "PASS" and "fix" not in r:
        r["fix"] = "Re-derive and cite."
frag["rows"] = rows_out
passed = sum(1 for r in rows_out if r["status"] == "PASS")
failed = [r["id"] for r in rows_out if r["status"] != "PASS"]
frag["round"] = 29
frag["verified_at"] = datetime.now(UTC).replace(microsecond=0).isoformat()
frag["verdict"] = "PASS" if passed == len(rows_out) else "FAIL"
frag["summary"] = {"rows": len(rows_out), "pass": passed, "fail": sum(1 for r in rows_out if r["status"] == "FAIL"),
                   "unverifiable": sum(1 for r in rows_out if r["status"] == "UNVERIFIABLE"), "mutants": 0, "fail_ids": failed}
frag["notes"] = frag["notes"] + (" ROUND 29 (architect ruling on R26-diff-coverage): the three in-scope files that had no row are named by R29-glossary-json, R29-program-json and R29-rubric-test-mjs; out-of-scope files are decided by R29-* rows with owners; the row is restated with counts. Rows added: " + str(len(new_rows)) + ".")
json.dump(frag, open(frag_path, "w", encoding="utf-8"), indent=1, ensure_ascii=False)
open(frag_path, "a", encoding="utf-8").write("\n")
open(f"{CK}/{LOG}/diff_coverage_round29.out", "w", encoding="utf-8").write(R["R26-diff-coverage"][2] + "\n\nUNNAMED: " + str(unnamed) + "\nIN SCOPE: " + str(in_scope) + "\n")
print("rows", len(rows_out), "pass", passed, "fail", failed, "unnamed", unnamed, "in-scope unnamed", in_scope_unnamed)
